        // Cycle 1 of decrement
        load = 0;
        @(posedge clk);
        #1;
        if (tc !== 1'b0) errors = errors + 1; // count should be 2

        // Cycle 2 of decrement
        @(posedge clk);
        #1;
        if (tc !== 1'b0) errors = errors + 1; // count should be 1

        // Cycle 3 of decrement (reaches 0)
        @(posedge clk);
        #1;
        if (tc !== 1'b1) errors = errors + 1; // count should be 0, tc asserted

        // Test 3: Stay at 0 when load = 0
        @(posedge clk);
        #1;
        if (tc !== 1'b1) errors = errors + 1;

        // Test 4: Reload while counting / at zero
        // Load with 1
        @(posedge clk);
        load = 1;
        data = 10'd1;
        @(posedge clk);
        #1;
        if (tc !== 1'b0) errors = errors + 1;

        // Decrement once to reach 0
        load = 0;
        @(posedge clk);
        #1;
        if (tc !== 1'b1) errors = errors + 1;

        // Test 5: Load with 0 directly
        @(posedge clk);
        load = 1;
        data = 10'd0;
        @(posedge clk);
        #1;
        if (tc !== 1'b1) errors = errors + 1;

        // Finish tests and report results
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
